<!doctype html><html lang="fr"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Thiebapower · Tarifs</title><link rel="stylesheet" href="/style.css"><main><h1>Paramètres de location</h1><section><form action="/admin/prices" method="post"><label>Location FCFA<input type="number" min="0" name="rental_fee" value="<?= (int)$prices['rental_fee'] ?>"></label><label>Caution par défaut FCFA<input type="number" min="0" name="default_deposit" value="<?= (int)$prices['default_deposit'] ?>"></label><label>Durée incluse en minutes<input type="number" min="1" name="duration_minutes" value="<?= (int)$prices['duration_minutes'] ?>"></label><label>Pourcentage par heure supplémentaire<input type="number" min="0" max="100" name="late_percent" value="<?= (int)$prices['late_percent'] ?>"></label><button>Enregistrer</button></form></section><section><h2>Batteries</h2><form action="/admin/batteries" method="post"><label>Numéro de série<input name="serial" required></label><label>Caution spécifique FCFA (vide = tarif par défaut)<input name="deposit_override" type="number" min="0"></label><button>Ajouter ou modifier</button></form><ul><?php foreach($batteries as $b):?><li><?=htmlspecialchars($b['serial'])?> · <?=htmlspecialchars($b['status'])?> · caution <?=htmlspecialchars((string)($b['deposit_override']??'défaut'))?></li><?php endforeach ?></ul></section></main></html>